// Mapa del mundo — continentes reconocibles al primer vistazo mediante miles de
// puntos azul oscuro sobre negro (sin fronteras, sin nombres, sin colores) + red
// de conexiones entre grandes centros financieros + partículas de profundidad.
// Coordenadas convertidas de lat/long a un viewBox equirectangular 1000x500 vía
// x=(lon+180)/360*1000, y=(90-lat)/180*500.

export type MapRegion = 'namerica' | 'europe' | 'asia' | 'oceania'

interface MapNode { id: string; region: MapRegion; x: number; y: number }

