function generateAmbientParticles(): { x: number; y: number; dur: number; delay: number }[] {
  const rnd = mulberry32(90417)
  const out: { x: number; y: number; dur: number; delay: number }[] = []
  for (let i = 0; i < 46; i++) {
    out.push({ x: rnd() * 1000, y: rnd() * 500, dur: 14 + rnd() * 16, delay: rnd() * 10 })
  }
  return out
}

const AMBIENT = generateAmbientParticles()


interface Props {
  /** Preparado para el futuro: sube ligeramente la intensidad de una región según la sesión de mercado abierta. No implementado todavía. */
  activeSession?: MapRegion
  /** Preparado para el futuro: ilumina la región de un evento macro (FOMC→namerica, BCE→europe, BoJ→asia). No implementado todavía. */
  highlightRegion?: MapRegion
}

export function WorldMapHotspots({ activeSession, highlightRegion }: Props) {
  const byId = (id: string) => NODES.find(n => n.id === id)!
  const boosted = (region: MapRegion) => region === activeSession || region === highlightRegion

  return (
    <svg viewBox="0 0 1000 500" className="w-full h-full" preserveAspectRatio="xMidYMid meet">
      {/* continentes: puntos reales sobre geometría de costas (world-atlas land-50m) */}
      {LAND_DOTS.map(([x, y], i) => (
        <circle key={i} cx={x} cy={y} r={0.8} fill="#237a22" fillOpacity={0.65} />
      ))}

      {/* profundidad: partículas ambientales muy pequeñas, movimiento extremadamente lento */}
      {AMBIENT.map((p, i) => (
        <circle key={i} cx={p.x} cy={p.y} r={0.5} fill="#3B82F6"
          style={{ animation: `float-particle ${p.dur}s ease-in-out ${p.delay}s infinite` }} />
      ))}

      {/* red financiera — curvas suaves, sin cruces caóticos */}
      {LINKS.map(([a, b], i) => {
        const na = byId(a), nb = byId(b)
        const mx = (na.x + nb.x) / 2
        const dist = Math.hypot(nb.x - na.x, nb.y - na.y)
        const my = Math.min(na.y, nb.y) - Math.min(dist * 0.18, 55)
        const pathId = `link-${i}`
        const dur = 9 + (i % 5) * 2.5
        return (
          <g key={pathId}>
            <path id={pathId} d={`M${na.x},${na.y} Q${mx},${my} ${nb.x},${nb.y}`}
              fill="none" stroke="#3B82F6" strokeOpacity={0.18} strokeWidth={0.6} />
            <circle r={1.3} fill="#22D3EE" fillOpacity={0.8}>
              <animateMotion dur={`${dur}s`} begin={`${i * 0.9}s`} repeatCount="indefinite" rotate="auto">
                <mpath href={`#${pathId}`} />
              </animateMotion>
              <animate attributeName="opacity" values="0;0.8;0.8;0" keyTimes="0;0.08;0.85;1"
                dur={`${dur}s`} begin={`${i * 0.9}s`} repeatCount="indefinite" />
            </circle>
          </g>
        )
      })}

      {/* los 10 centros financieros — pulso suave, sin etiqueta ni icono */}
      {NODES.map((n, i) => {
        const boost = boosted(n.region)
        return (
          <g key={n.id}>
            <circle cx={n.x} cy={n.y} r={10} fill="#3B82F6"
              fillOpacity={boost ? 0.3 : 0.16}
              style={{ animation: `breathe-node 4.8s ease-in-out ${i * 0.4}s infinite` }} />
            <circle cx={n.x} cy={n.y} r={2.2} fill={boost ? '#22D3EE' : '#3B82F6'} />
          </g>
        )
      })}
    </svg>
  )
}
